{
  "concept": "The cross-ratio of four collinear points is invariant under central projection: any transversal cutting a pencil of four rays from a center O yields the same cross-ratio value, even when one intersection point escapes to infinity.",
  "figureType": "diagram",
  "elements": [
    "Center of projection O (large black dot, left of scene, label 'O')",
    "Four black rays emanating from O, fanning out to the right (ray 1 lowest/descending, rays 2 and 3 shallow upward, ray 4 steepest upward), each drawn as an extended line past the last intersection",
    "Transversal line 1 (magenta, near-vertical, left of scene) cutting the four rays at P1 (lowest, on ray 1), P2, P3, P4 (highest, on ray 4)",
    "Transversal line 2 (magenta, steeply descending to the right) cutting the rays at Q1 (bottom right, on ray 1), Q2, Q3, Q4 (top, on ray 4)",
    "Transversal line 3 (magenta, shallow, descending to the right, drawn parallel to ray 1) cutting rays 4, 3, 2 at R4, R3, R2 and meeting ray 1 only at infinity",
    "Black dots marking P1–P4, Q1–Q4, R2–R4 with bold serif subscripted labels",
    "Annotation at far right: 'R1 → ∞' with an arrow along ray 1, marking the missing fourth intersection",
    "Readout panel showing cross-ratio value for each transversal: CR(P1,P2;P3,P4), CR(Q1,Q2;Q3,Q4), CR(R1,R2;R3,R4)",
    "Cross-ratio formula caption: CR = (|AC|·|BD|)/(|BC|·|AD|)",
    "Optional segment-length brackets/measure labels along the active transversal",
    "Legend: black = projection rays from O, magenta = transversal lines carrying the four collinear points"
  ],
  "interactions": [
    {
      "id": "dragTransversalPoints",
      "type": "drag",
      "teaches": "Sliding a whole transversal (or re-aiming a ray) moves every P, Q, R point along its ray, yet the three cross-ratio readouts stay locked to the same number — the ratio depends on the pencil, not on where you cut it."
    },
    {
      "id": "dragCenterO",
      "type": "drag",
      "teaches": "Moving the center of projection O reshapes the whole fan and all intersection spacings, but every transversal still reports the identical cross-ratio — invariance holds for any projection center."
    },
    {
      "id": "rLineSlope",
      "type": "slider",
      "teaches": "As the third transversal rotates toward being parallel to ray 1, R1 slides off to infinity; the cross-ratio does not blow up but smoothly reaches the limiting form where the two terms involving R1 cancel.",
      "label": "Slope of R-transversal (→ parallel to ray OP₁Q₁)",
      "range": [-0.6, 0.0, 0.01],
      "default": -0.18
    },
    {
      "id": "activeTransversal",
      "type": "toggle",
      "teaches": "Isolating one transversal at a time shows which four distances enter its cross-ratio, and that the same four rays generate all three sets.",
      "label": "Highlight point set",
      "options": ["all", "P", "Q", "R"],
      "default": "all"
    },
    {
      "id": "showDistances",
      "type": "toggle",
      "teaches": "Reading the actual segment lengths makes concrete that individual distances and their simple ratios all change, while the particular double ratio does not.",
      "label": "Show segment lengths",
      "default": false
    }
  ],
  "demo_steps": [
    {
      "title": "A pencil of four rays",
      "narration": "Four rays leave the projection center O. Any line crossing them picks out four collinear points — here P₁…P₄ on the first magenta transversal.",
      "state": { "activeTransversal": "P", "showDistances": false, "rLineSlope": -0.18 }
    },
    {
      "title": "Distances are not invariant",
      "narration": "Turn on the segment lengths: the spacings between P₁, P₂, P₃, P₄ are completely different from those between Q₁, Q₂, Q₃, Q₄. Simple ratios of lengths are destroyed by projection.",
      "state": { "activeTransversal": "Q", "showDistances": true, "rLineSlope": -0.18 }
    },
    {
      "title": "The double ratio survives",
      "narration": "Compute (|AC|·|BD|)/(|BC|·|AD|) on each transversal. Despite the wildly different spacings, all three readouts show the same number — that is the cross-ratio.",
      "state": { "activeTransversal": "all", "showDistances": true, "rLineSlope": -0.18 }
    },
    {
      "title": "Sending R₁ to infinity",
      "narration": "Rotate the third transversal until it is parallel to the ray through P₁ and Q₁. R₁ escapes to infinity, yet the cross-ratio settles to the same value — the infinite terms cancel in the limit.",
      "state": { "activeTransversal": "R", "showDistances": false, "rLineSlope": 0.0 }
    },
    {
      "title": "Any center, same invariant",
      "narration": "Drag O anywhere and drag the transversals freely. The figure deforms completely, but the three cross-ratio values move together and stay equal.",
      "state": { "activeTransversal": "all", "showDistances": false, "rLineSlope": -0.1 }
    }
  ],
  "keyInsight": "Projection scrambles lengths and even simple length ratios, but the ratio-of-ratios of four collinear points is preserved — so the cross-ratio is a measurement you can read off a single image and trust in the 3D world, even when one of the four points is the vanishing point at infinity.",
  "reconstructionNotes": "Wide landscape layout. Place O as a large black dot at far left, roughly mid-height. Four black straight rays fan rightward from O: the lowest descends to the bottom-right corner, two middle rays rise gently, the top ray rises steeply to the upper-right; draw each ray extending beyond its last labeled intersection. Three magenta transversal lines cross the pencil: (1) a near-vertical line in the left third, giving P₁ at the bottom through P₄ at the top; (2) a steeply right-descending line in the middle, giving Q₄ near the top and Q₁ at the bottom right; (3) a long shallow right-descending line across the upper right, giving R₄, R₃, R₂ from left to right and drawn visibly parallel to the lowest ray so it never meets it. Mark every intersection with a filled black disc and a bold serif label with numeric subscript, labels offset just below/right of their dot. At the far right, along the lowest ray, add the annotation 'R₁ → ∞' with a small rightward arrow. Include a compact readout box (top-left or bottom-right) listing the three cross-ratio values and the formula CR = (AC·BD)/(BC·AD); values should visibly agree to several decimals. Magenta (#E8175D) for transversals and their emphasis, pure black for rays, points and labels, white background. When a point set is highlighted, dim the other two transversals to light gray."
}

