/* ---------- small vector helpers ---------- */
function dir(a) { return { x: Math.cos(a), y: Math.sin(a) }; }
function cross(a, b) { return a.x * b.y - a.y * b.x; }
function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
function inCanvas(p, m) { m = (m == null) ? 6 : m; return p.x >= -m && p.x <= W + m && p.y >= -m && p.y <= H + m; }
function fmt(v) { return (isFinite(v)) ? v.toFixed(4) : '—'; }

function rayEdge(O, d) {
  var tm = Infinity;
  if (d.x > 1e-9) tm = Math.min(tm, (W - O.x) / d.x); else if (d.x < -1e-9) tm = Math.min(tm, (0 - O.x) / d.x);
  if (d.y > 1e-9) tm = Math.min(tm, (H - O.y) / d.y); else if (d.y < -1e-9) tm = Math.min(tm, (0 - O.y) / d.y);
  if (!isFinite(tm)) tm = W;
  return { x: O.x + tm * d.x, y: O.y + tm * d.y };
