  function slab(p0, dd, mn, mx) {
    if (Math.abs(dd) < 1e-9) { if (p0 < mn || p0 > mx) { lo = 1; hi = 0; } return; }
    var a = (mn - p0) / dd, b = (mx - p0) / dd, t;
    if (a > b) { t = a; a = b; b = t; }
    lo = Math.max(lo, a); hi = Math.min(hi, b);
