/* ---------- geometry ---------- */
function computeTrans(key, anchor, td, rd) {
  var info = { key: key, anchor: anchor, d: td, pts: [] };
  for (var i = 0; i < 4; i++) {
    var den = cross(rd[i], td);
    var w = { x: anchor.x - S.O.x, y: anchor.y - S.O.y };
    if (Math.abs(den) < 1e-10) { info.pts.push({ inf: true }); continue; }
    var s = cross(w, rd[i]) / den;
    info.pts.push({ inf: false, s: s, p: { x: anchor.x + s * td.x, y: anchor.y + s * td.y } });
  }
  var q = info.pts;
  if (q[0].inf) {
    info.cr = (q[3].s - q[1].s) / (q[2].s - q[1].s);
    info.limit = true;
  } else {
    info.cr = ((q[2].s - q[0].s) * (q[3].s - q[1].s)) / ((q[2].s - q[1].s) * (q[3].s - q[0].s));
    info.limit = false;
  }
  return info;
}

var OFFS = {
