function drawRays(O, rd) {
  for (var i = 0; i < 4; i++) {
    (function (i) {
      var e = rayEdge(O, rd[i]);
      gRay.line(O.x, O.y, e.x, e.y).stroke({ color: '#000', width: 2.4, linecap: 'round' });
      var hit = gRay.line(O.x, O.y, e.x, e.y).stroke({ color: '#000', width: 14, opacity: 0 })
        .attr('pointer-events', 'stroke').css('cursor', 'help');
      hit.on('mousemove', function (ev) { showTooltip('Ray ' + (i + 1) + ' of the pencil through O', ev); })
        .on('mouseleave', hideTooltip)
        .on('click', function () {
          showPopup('A pencil of four rays',
            'All four black lines pass through the projection centre O. Every transversal that cuts this pencil records the same cross-ratio, so the number belongs to the pencil of rays itself, not to the line you cut it with.');
        });
      var hx = e.x - 15 * rd[i].x, hy = e.y - 15 * rd[i].y;
      var h = gRay.circle(10).center(hx, hy).fill('#fff').stroke({ color: '#8f8f8f', width: 1.3 }).css('cursor', 'grab');
      h.on('pointerdown', function (ev) { startDrag({ kind: 'ray', idx: i }, ev); });
      h.on('mousemove', function (ev) { showTooltip('Drag to re-aim ray ' + (i + 1) + ': all three cross-ratios change together — and stay equal.', ev); })
