  for (i = 0; i < 4; i++) if (!info.pts[i].inf && inCanvas(info.pts[i].p, 70)) ss.push(info.pts[i].s);
  if (ss.length < 2) { for (i = 0; i < 4; i++) if (!info.pts[i].inf) ss.push(info.pts[i].s); }
  if (ss.length < 2) return;
  var s0 = Math.min.apply(null, ss) - 32, s1 = Math.max.apply(null, ss) + 32;
  var cl = clipSeg(info.anchor, info.d, s0, s1, 2);
  if (cl[1] <= cl[0]) return;
  var a = { x: info.anchor.x + cl[0] * info.d.x, y: info.anchor.y + cl[0] * info.d.y };
  var b = { x: info.anchor.x + cl[1] * info.d.x, y: info.anchor.y + cl[1] * info.d.y };
  gTrans.line(a.x, a.y, b.x, b.y).stroke({ color: on ? MAGENTA : DIMLINE, width: on ? 3.5 : 2.4, linecap: 'round' });
  var hit = gTrans.line(a.x, a.y, b.x, b.y).stroke({ color: '#000', width: 18, opacity: 0 })
    .attr('pointer-events', 'stroke').css('cursor', 'move');
  hit.on('pointerdown', function (ev) { startDrag({ kind: 'trans', idx: { P: 0, Q: 1, R: 2 }[info.key] }, ev); });
  hit.on('mousemove', function (ev) {
    showTooltip('Transversal ' + info.key + ' — drag to slide it. Its four points move, its cross-ratio does not.', ev);
  }).on('mouseleave', hideTooltip)
    .on('click', function () {
      showPopup('Transversal ' + info.key,
        'This magenta line cuts the four rays in four collinear points. Their cross-ratio (|AC|·|BD|)/(|BC|·|AD|) equals ' + fmt(info.cr) +
        ' — exactly the value read off the other transversals, however differently the individual distances come out.');
    });
}

function drawPoints(info) {
  var on = isActive(info.key);
  for (var i = 0; i < 4; i++) {
    var q = info.pts[i];
    if (q.inf || !inCanvas(q.p, -4)) continue;
    (function (i, q) {
      var name = info.key + '\u2081\u2082\u2083\u2084'.charAt(i);
      var c = gDot.circle(15).center(q.p.x, q.p.y).fill(on ? '#000' : DIMDOT).css('cursor', 'pointer');
      c.on('mousemove', function (ev) { showTooltip(name + ' — transversal ' + info.key + ' meets ray ' + (i + 1), ev); })
        .on('mouseleave', hideTooltip)
        .on('click', function () {
          showPopup(name,
            'The intersection of transversal ' + info.key + ' with ray ' + (i + 1) + '. Slide the transversal or move O: this point runs along its ray and all the spacings change, yet the double ratio of the four points stays at ' + fmt(info.cr) + '.');
        });
      var o = OFFS[info.key][i];
      labelSub(gLab, info.key, '\u2081\u2082\u2083\u2084'.charAt(i), q.p.x + o[0], q.p.y + o[1], 21, on ? '#000' : DIMTXT);
    })(i, q);
  }
}

function drawDistances(res) {
  for (var i = 0; i < 3; i++) {
    var info = res[i];
    if (!isActive(info.key)) continue;
    var d = info.d, n = { x: -d.y, y: d.x };
    if (Math.abs(d.y) > Math.abs(d.x)) { if (n.x > 0) { n.x = -n.x; n.y = -n.y; } }
    else { if (n.y > 0) { n.x = -n.x; n.y = -n.y; } }
    for (var j = 0; j < 3; j++) {
      var a = info.pts[j], b = info.pts[j + 1];
      if (a.inf || b.inf) continue;
      if (!inCanvas(a.p, -4) || !inCanvas(b.p, -4)) continue;
      var mx = (a.p.x + b.p.x) / 2 + n.x * 15, my = (a.p.y + b.p.y) / 2 + n.y * 15;
      txt(gDist, Math.abs(b.s - a.s).toFixed(0), mx, my, 11, '#555', 'middle');
    }
  }
}

function drawAnno(rInfo) {
