  var r = gBox.rect(w, h).move(x, y).radius(5).fill({ color: '#fff', opacity: 0.93 }).stroke({ color: '#e4e4e4', width: 1 }).css('cursor', 'help');
  txt(gBox, 'CR = (AC\u00B7BD) / (BC\u00B7AD)', x + 11, y + 21, 13, '#333', 'start', 'bold');
