  var O = S.O, rd = [], i;
  for (i = 0; i < 4; i++) rd.push(dir(S.rayAng[i]));
  drawRays(O, rd);
  var tdefs = [
    { key: 'P', anchor: S.pAnchor, d: dir(S.pAng) },
    { key: 'Q', anchor: S.qAnchor, d: dir(S.qAng) },
    { key: 'R', anchor: S.rAnchor, d: dir(S.rayAng[0] + 0.5 * S.rSlider * S.rSlider) }
