  if (!drag) return;
  var w = toWorld(ev);
  if (drag.t.kind === 'O') {
    S.O.x = clamp(drag.orig.x + (w.x - drag.start.x), 10, W * 0.5);
    S.O.y = clamp(drag.orig.y + (w.y - drag.start.y), 25, H - 15);
  } else if (drag.t.kind === 'trans') {
    var a = anchorOf(drag.t.idx);
    a.x = clamp(drag.orig.x + (w.x - drag.start.x), 90, W - 90);
    a.y = clamp(drag.orig.y + (w.y - drag.start.y), 20, H - 20);
  } else if (drag.t.kind === 'ray') {
    var i = drag.t.idx;
    var ang = Math.atan2(w.y - S.O.y, w.x - S.O.x);
