    txt(gBox, s, x + 11, y + 40 + i * 16, 12, c, 'start', 'normal');
  }
  r.on('mousemove', function (ev) { showTooltip('The same number on all three transversals — that is the invariant.', ev); })
    .on('mouseleave', hideTooltip)
    .on('click', function () {
      showPopup('The cross-ratio',
        'For four collinear points A,B,C,D the cross-ratio is (|AC|·|BD|)/(|BC|·|AD|), using signed lengths. Individual distances and simple ratios are destroyed by central projection; this particular ratio-of-ratios is not, so it can be read off one image and trusted in the 3D scene.');
    });
}

function updateReadout(res) {
  var q = res[2].pts[0];
  var dist = res[2].limit ? '\u221E' : (Math.abs(q.s) > 2600 ? Math.round(Math.abs(q.s)) + ' px (off figure)' : Math.round(Math.abs(q.s)) + ' px');
  var el = document.getElementById('readout');
  if (!el) return;
  el.innerHTML =
    'CR(P\u2081P\u2082;P\u2083P\u2084) = ' + fmt(res[0].cr) + '<br>' +
    'CR(Q\u2081Q\u2082;Q\u2083Q\u2084) = ' + fmt(res[1].cr) + '<br>' +
    'CR(R\u2081R\u2082;R\u2083R\u2084) = ' + fmt(res[2].cr) + (res[2].limit ? '  \u2190 |R\u2082R\u2084|/|R\u2082R\u2083|' : '') + '<br>' +
    'dist(R\u2082,R\u2081) = ' + dist;
}

/* ---------- master render ---------- */
function render() {
  [gRay, gTrans, gDist, gDot, gLab, gAnno, gBox].forEach(function (g) { g.clear(); });
  var O = S.O, rd = [], i;
  for (i = 0; i < 4; i++) rd.push(dir(S.rayAng[i]));
  drawRays(O, rd);
  var tdefs = [
    { key: 'P', anchor: S.pAnchor, d: dir(S.pAng) },
    { key: 'Q', anchor: S.qAnchor, d: dir(S.qAng) },
    { key: 'R', anchor: S.rAnchor, d: dir(S.rayAng[0] + 0.5 * S.rSlider * S.rSlider) }
  ];
  var res = tdefs.map(function (td) { return computeTrans(td.key, td.anchor, td.d, rd); });
  res.forEach(drawTransversal);
  res.forEach(drawPoints);
  if (S.showDist) drawDistances(res);
  drawAnno(res[2]);
  drawO(O);
  drawBox(res);
  updateReadout(res);
}

/* ---------- dragging ---------- */
var drag = null;
function toWorld(ev) {
  var p = svgNode.createSVGPoint();
  p.x = ev.clientX; p.y = ev.clientY;
  return p.matrixTransform(svgNode.getScreenCTM().inverse());
}
function anchorOf(i) { return [S.pAnchor, S.qAnchor, S.rAnchor][i]; }
function startDrag(target, ev) {
  if (ev.preventDefault) ev.preventDefault();
  var w = toWorld(ev);
  drag = { t: target, start: w, orig: null };
  if (target.kind === 'O') drag.orig = { x: S.O.x, y: S.O.y };
  if (target.kind === 'trans') { var a = anchorOf(target.idx); drag.orig = { x: a.x, y: a.y }; }
  hideTooltip();
}
window.addEventListener('pointermove', function (ev) {
  if (!drag) return;
  var w = toWorld(ev);
  if (drag.t.kind === 'O') {
    S.O.x = clamp(drag.orig.x + (w.x - drag.start.x), 10, W * 0.5);
    S.O.y = clamp(drag.orig.y + (w.y - drag.start.y), 25, H - 15);
  } else if (drag.t.kind === 'trans') {
    var a = anchorOf(drag.t.idx);
    a.x = clamp(drag.orig.x + (w.x - drag.start.x), 90, W - 90);
    a.y = clamp(drag.orig.y + (w.y - drag.start.y), 20, H - 20);
  } else if (drag.t.kind === 'ray') {
    var i = drag.t.idx;
    var ang = Math.atan2(w.y - S.O.y, w.x - S.O.x);
    if (w.x - S.O.x < 5) ang = S.rayAng[i];
    var hi = (i === 0) ? 1.25 : S.rayAng[i - 1] - 0.07;
    var lo = (i === 3) ? -1.30 : S.rayAng[i + 1] + 0.07;
    S.rayAng[i] = clamp(ang, lo, hi);
  }
  render();
});
window.addEventListener('pointerup', function () { drag = null; });
window.addEventListener('pointercancel', function () { drag = null; });

/* ---------- controls ---------- */
function update_rLineSlope(v) { S.rSlider = v; render(); }
function toggle_activeTransversal(v) { S.active = v; render(); }
function toggle_showDistances(on) { S.showDist = on; render(); }
function trigger_reset() {
  S = JSON.parse(JSON.stringify(DEFAULTS));
  document.getElementById('rLineSlopeInput').value = S.rSlider;
  document.getElementById('rLineSlopeVal').value = S.rSlider.toFixed(2);
  document.getElementById('activeTransversalInput').value = S.active;
  document.getElementById('showDistancesInput').checked = S.showDist;
  render();
}

/* ---------- demo steps ---------- */
var steps = [
  {
    title: '1 · A pencil of four rays',
    narration: 'Four rays leave the projection centre O. Any line crossing them picks out four collinear points — here P₁…P₄ on the first magenta transversal.',
    state: { activeTransversal: 'all', showDistances: false, rLineSlope: -0.18, O: { x: 43, y: 292 } }
  },
  {
    title: '2 · Distances are not invariant',
    narration: 'Segment lengths are on: the spacings of Q₁…Q₄ are nothing like those of P₁…P₄. Simple ratios of lengths are destroyed by projection.',
    state: { activeTransversal: 'Q', showDistances: true, rLineSlope: -0.18, O: { x: 43, y: 292 } }
  },
  {
    title: '3 · The double ratio survives',
    narration: 'Compute (|AC|·|BD|)/(|BC|·|AD|) on each transversal. Despite the wildly different spacings, all three readouts show the same number — the cross-ratio.',
    state: { activeTransversal: 'all', showDistances: true, rLineSlope: -0.18, O: { x: 43, y: 292 } }
  },
  {
    title: '4 · Sending R₁ to infinity',
    narration: 'Slide the slope to 0: the third transversal becomes parallel to the ray through P₁ and Q₁. R₁ escapes to infinity, yet the cross-ratio settles on the same value — the infinite terms cancel and CR = |R₂R₄|/|R₂R₃|.',
    state: { activeTransversal: 'R', showDistances: false, rLineSlope: 0, O: { x: 43, y: 292 } }
  },
  {
    title: '5 · Any centre, same invariant',
    narration: 'O has been moved and the whole figure deforms. Drag O, the transversals or the ray tips yourself: the three cross-ratio values move together and stay equal.',
    state: { activeTransversal: 'all', showDistances: false, rLineSlope: -0.1, O: { x: 95, y: 196 } }
  }
];
var stepIdx = 0;
function applyStep(i) {
  stepIdx = (i + steps.length) % steps.length;
  var st = steps[stepIdx], s = st.state;
  document.getElementById('stepTitle').textContent = st.title;
  document.getElementById('demoNarration').textContent = st.narration;
  document.getElementById('stepLabel').textContent = (stepIdx + 1) + ' / ' + steps.length;
  var sl = document.getElementById('rLineSlopeInput');
  sl.value = s.rLineSlope;
  document.getElementById('rLineSlopeVal').value = (+s.rLineSlope).toFixed(2);
  S.rSlider = +s.rLineSlope;
  var sel = document.getElementById('activeTransversalInput');
  sel.value = s.activeTransversal; S.active = s.activeTransversal;
  var cb = document.getElementById('showDistancesInput');
  cb.checked = !!s.showDistances; S.showDist = !!s.showDistances;
  if (s.O) { S.O.x = s.O.x; S.O.y = s.O.y; }
  render();
}
function nextStep() { applyStep(stepIdx + 1); }
function prevStep() { applyStep(stepIdx - 1); }

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: The cross-ratio of four collinear points is invariant under central projection: any transversal cutting a pencil of four rays from a center O yields the same cross-ratio value, even when one intersection point escapes to infinity.
KEY INSIGHT (what students should walk away understanding): Projection scrambles lengths and even simple length ratios, but the ratio-of-ratios of four collinear points is preserved — so the cross-ratio is a measurement you can read off a single image and trust in the 3D world, even when one of the four points is the vanishing point at infinity.
DEMO STEPS: 5 guided steps — implement the step player in #ui

FULL BLUEPRINT:
{
  "concept": "The cross-ratio of four collinear points is invariant under central projection: any transversal cutting a pencil of four rays from a center O yields the same cross-ratio value, even when one intersection point escapes to infinity.",
  "figureType": "diagram",
  "elements": [
    "Center of projection O (large black dot, left of scene, label 'O')",
    "Four black rays emanating from O, fanning out to the right (ray 1 lowest/descending, rays 2 and 3 shallow upward, ray 4 steepest upward), each drawn as an extended line past the last intersection",
    "Transversal line 1 (magenta, near-vertical, left of scene) cutting the four rays at P1 (lowest, on ray 1), P2, P3, P4 (highest, on ray 4)",
    "Transversal line 2 (magenta, steeply descending to the right) cutting the rays at Q1 (bottom right, on ray 1), Q2, Q3, Q4 (top, on ray 4)",
    "Transversal line 3 (magenta, shallow, descending to the right, drawn parallel to ray 1) cutting rays 4, 3, 2 at R4, R3, R2 and meeting ray 1 only at infinity",
    "Black dots marking P1–P4, Q1–Q4, R2–R4 with bold serif subscripted labels",
    "Annotation at far right: 'R1 → ∞' with an arrow along ray 1, marking the missing fourth intersection",
    "Readout panel showing cross-ratio value for each transversal: CR(P1,P2;P3,P4), CR(Q1,Q2;Q3,Q4), CR(R1,R2;R3,R4)",
    "Cross-ratio formula caption: CR = (|AC|·|BD|)/(|BC|·|AD|)",
    "Optional segment-length brackets/measure labels along the active transversal",
    "Legend: black = projection rays from O, magenta = transversal lines carrying the four collinear points"
  ],
  "interactions": [
    {
      "id": "dragTransversalPoints",
      "type": "drag",
      "teaches": "Sliding a whole transversal (or re-aiming a ray) moves every P, Q, R point along its ray, yet the three cross-ratio readouts stay locked to the same number — the ratio depends on the pencil, not on where you cut it."
    },
    {
      "id": "dragCenterO",
      "type": "drag",
      "teaches": "Moving the center of projection O reshapes the whole fan and all intersection spacings, but every transversal still reports the identical cross-ratio — invariance holds for any projection center."
    },
    {
      "id": "rLineSlope",
      "type": "slider",
      "teaches": "As the third transversal rotates toward being parallel to ray 1, R1 slides off to infinity; the cross-ratio does not blow up but smoothly reaches the limiting form where the two terms involving R1 cancel.",
      "label": "Slope of R-transversal (→ parallel to ray OP₁Q₁)",
      "range": [
        -0.6,
        0,
        0.01
      ],
      "default": -0.18
    },
    {
      "id": "activeTransversal",
      "type": "toggle",
      "teaches": "Isolating one transversal at a time shows which four distances enter its cross-ratio, and that the same four rays generate all three sets.",
      "label": "Highlight point set",
      "options": [
        "all",
        "P",
        "Q",
        "R"
      ],
      "default": "all"
    },
    {
      "id": "showDistances",
      "type": "toggle",
      "teaches": "Reading the actual segment lengths makes concrete that individual distances and their simple ratios all change, while the particular double ratio does not.",
      "label": "Show segment lengths",
      "default": false
    }
  ],
  "demo_steps": [
    {
      "title": "A pencil of four rays",
      "narration": "Four rays leave the projection center O. Any line crossing them picks out four collinear points — here P₁…P₄ on the first magenta transversal.",
      "state": {
        "activeTransversal": "P",
        "showDistances": false,
        "rLineSlope": -0.18
      }
    },
    {
      "title": "Distances are not invariant",
      "narration": "Turn on the segment lengths: the spacings between P₁, P₂, P₃, P₄ are completely different from those between Q₁, Q₂, Q₃, Q₄. Simple ratios of lengths are destroyed by projection.",
      "state": {
        "activeTransversal": "Q",
        "showDistances": true,
        "rLineSlope": -0.18
      }
    },
    {
      "title": "The double ratio survives",
      "narration": "Compute (|AC|·|BD|)/(|BC|·|AD|) on each transversal. Despite the wildly different spacings, all three readouts show the same number — that is the cross-ratio.",
      "state": {
        "activeTransversal": "all",
        "showDistances": true,
        "rLineSlope": -0.18
      }
    },
    {
      "title": "Sending R₁ to infinity",
      "narration": "Rotate the third transversal until it is parallel to the ray through P₁ and Q₁. R₁ escapes to infinity, yet the cross-ratio settles to the same value — the infinite terms cancel in the limit.",
      "state": {
        "activeTransversal": "R",
        "showDistances": false,
        "rLineSlope": 0
      }
    },
    {
      "title": "Any center, same invariant",
      "narration": "Drag O anywhere and drag the transversals freely. The figure deforms completely, but the three cross-ratio values move together and stay equal.",
      "state": {
        "activeTransversal": "all",
        "showDistances": false,
        "rLineSlope": -0.1
      }
    }
  ],
  "keyInsight": "Projection scrambles lengths and even simple length ratios, but the ratio-of-ratios of four collinear points is preserved — so the cross-ratio is a measurement you can read off a single image and trust in the 3D world, even when one of the four points is the vanishing point at infinity.",
  "reconstructionNotes": "Wide landscape layout. Place O as a large black dot at far left, roughly mid-height. Four black straight rays fan rightward from O: the lowest descends to the bottom-right corner, two middle rays rise gently, the top ray rises steeply to the upper-right; draw each ray extending beyond its last labeled intersection. Three magenta transversal lines cross the pencil: (1) a near-vertical line in the left third, giving P₁ at the bottom through P₄ at the top; (2) a steeply right-descending line in the middle, giving Q₄ near the top and Q₁ at the bottom right; (3) a long shallow right-descending line across the upper right, giving R₄, R₃, R₂ from left to right and drawn visibly parallel to the lowest ray so it never meets it. Mark every intersection with a filled black disc and a bold serif label with numeric subscript, labels offset just below/right of their dot. At the far right, along the lowest ray, add the annotation 'R₁ → ∞' with a small rightward arrow. Include a compact readout box (top-left or bottom-right) listing the three cross-ratio values and the formula CR = (AC·BD)/(BC·AD); values should visibly agree to several decimals. Magenta (#E8175D) for transversals and their emphasis, pure black for rays, points and labels, white background. When a point set is highlighted, dim the other two transversals to light gray."
}

